html:
{% set is_draft = doc.docstatus == 0 %}
{% set requestor_full_name = frappe.db.get_value('User', doc.owner, 'full_name') if doc.owner else '' %}
{% set first_cc = '' %}{% for it in doc.items %}{% if it.cost_center and not first_cc %}{% set first_cc = it.cost_center %}{% endif %}{% endfor %}

<style>
@page { size: A4; margin: 6mm 8mm 6mm 8mm; }
body { font-family: Arial, sans-serif; font-size: 10px; color: #000; }
.trustbit-wrap { position: relative; }
.trustbit-header-table { width: 100%; border-collapse: collapse; border: none; padding: 0 0 6px 0; }
.trustbit-header-table td { border: none !important; padding: 0; vertical-align: middle; }
.trustbit-logo-cell { width: 110px; padding-left: 6px !important; }
.trustbit-logo-cell img { max-width: 95px; max-height: 75px; }
.trustbit-header-text { text-align: center; padding-right: 110px !important; }
.trustbit-header-bottom-rule { border-bottom: 2px solid #000; margin: 0 0 6px 0; height: 0; line-height: 0; }
.trustbit-cname { font-size: 20px; font-weight: bold; color: #000; letter-spacing: 0.5px; line-height: 1.2; }
.trustbit-caddr { font-size: 12px; font-weight: bold; text-decoration: underline; margin-top: 2px; }
.trustbit-cinfo { font-size: 10px; margin-top: 3px; color: #111; }
.trustbit-cinfo span { margin: 0 6px; }
.trustbit-title-block { text-align: center; margin: 6px 0 4px 0; }
.trustbit-draft-stamp { font-size: 13px; font-weight: bold; letter-spacing: 2px; margin-bottom: 2px; color: #cc0000; }
.trustbit-title { font-size: 18px; font-weight: bold; text-decoration: underline; letter-spacing: 1px; }
.trustbit-subtitle { font-size: 10px; color: #333; margin-top: 2px; }
.trustbit-info-table { width: 100%; border-collapse: collapse; margin: 4px 0 4px 0; }
.trustbit-info-table td { padding: 3px 6px; font-size: 11px; vertical-align: middle; border: 1px solid #000; }
.trustbit-info-label { font-weight: bold; width: 22%; background: #eee; text-align: center; }
.trustbit-info-value { width: 28%; text-align: center; }
.trustbit-items { width: 100%; border-collapse: collapse; margin: 4px 0 0 0; }
.trustbit-items th { background: #e8e8e8; border: 1px solid #000; padding: 4px 5px; font-size: 10px; text-align: center; font-weight: bold; }
.trustbit-items td { border: 1px solid #000; padding: 3px 6px; font-size: 10px; vertical-align: top; }
.trustbit-items .num { text-align: right; }
.trustbit-items .ctr { text-align: center; }
.trustbit-items .item-spec { font-size: 10px; color: #111; line-height: 1.4; }
.trustbit-section-heading { font-size: 12px; font-weight: bold; text-decoration: underline; margin: 8px 0 3px; }
.trustbit-terms-body { font-size: 11px; line-height: 1.5; padding: 0 4px; }
.trustbit-footer { margin-top: 12px; border-top: 1px solid #000; padding-top: 5px; text-align: center; font-size: 10px; color: #111; line-height: 1.4; }
.trustbit-footer .fname { font-weight: bold; font-size: 11px; color: #000; }
.trustbit-watermark { position: fixed; top: 35%; left: 8%; font-size: 110px; color: rgba(255,0,0,0.08); font-weight: bold; transform: rotate(-30deg); -webkit-transform: rotate(-30deg); z-index: 0; letter-spacing: 18px; pointer-events: none; }
</style>

<div class="trustbit-wrap">

{% if is_draft %}<div class="trustbit-watermark">DRAFT</div>{% endif %}

{% if letter_head and not no_letterhead %}<div class="letter-head">{{ letter_head | safe }}</div>{% endif %}

{% if not letter_head or no_letterhead %}
<table class="trustbit-header-table">
<tr>
  <td class="trustbit-logo-cell">
    <img src="/files/client_logo.png" alt="Trustbit" onerror="this.style.display='none'">
  </td>
  <td class="trustbit-header-text">
    <div class="trustbit-cname">TRUSTBIT BIOFUEL PVT LTD</div>
    <div class="trustbit-caddr">Bodi Junawani, Betul (M.P.)</div>
    <div class="trustbit-cinfo">
      <span><b>GSTN:-</b> 23AAJCB8781D1ZM</span>
    </div>
    <div class="trustbit-cinfo">
      <span><b>Email:-</b> trustbitbiofuelpvtld@gmail.com | <b>Mobile no:-</b> 7880138508</span>
    </div>
  </td>
</tr>
</table>
<div class="trustbit-header-bottom-rule"></div>
{% endif %}

<div class="trustbit-title-block">
  {% if is_draft %}<div class="trustbit-draft-stamp">DRAFT</div>{% endif %}
  <div class="trustbit-title">MATERIAL REQUEST</div>
  <div class="trustbit-subtitle">Internal requisition for Materials, services, or assets</div>
  <div class="trustbit-subtitle">Trustbit Biofuel Private Limited | Bodi Junawani, Betul (MP)</div>
</div>

<table class="trustbit-info-table">
<tr>
  <td class="trustbit-info-label">Request No</td>
  <td class="trustbit-info-value">{{ doc.name }}</td>
  <td class="trustbit-info-label">Date</td>
  <td class="trustbit-info-value">{{ frappe.format(doc.transaction_date, {'fieldtype': 'Date'}) }}</td>
</tr>
<tr>
  <td class="trustbit-info-label">Purpose</td>
  <td class="trustbit-info-value">{{ doc.material_request_type or '' }}</td>
  <td class="trustbit-info-label">Required By</td>
  <td class="trustbit-info-value">{{ frappe.format(doc.schedule_date, {'fieldtype': 'Date'}) if doc.schedule_date else '' }}</td>
</tr>
<tr>
  <td class="trustbit-info-label">Company</td>
  <td class="trustbit-info-value">{{ doc.company or '' }}</td>
  <td class="trustbit-info-label">Cost Center</td>
  <td class="trustbit-info-value">{{ first_cc or '' }}</td>
</tr>
<tr>
  <td class="trustbit-info-label">Requested By</td>
  <td class="trustbit-info-value">{{ requestor_full_name or doc.owner or '' }}</td>
  <td class="trustbit-info-label">Priority</td>
  <td class="trustbit-info-value">{{ doc.ts_priority or doc.priority or '' }}</td>
</tr>
<tr>
  <td class="trustbit-info-label">Project</td>
  <td class="trustbit-info-value">{{ doc.ts_project or doc.project or '' }}</td>
  <td class="trustbit-info-label">Status</td>
  <td class="trustbit-info-value">{{ doc.ts_mr_status or doc.status or '' }}</td>
</tr>
</table>

<table class="trustbit-items">
<thead>
<tr>
  <th style="width:30px">S.NO</th>
  <th style="width:80px">ITEM CODE</th>
  <th>ITEM NAME</th>
  <th>DESCRIPTION</th>
  <th>MAKE REMARK</th>
  <th style="width:50px">QTY</th>
  <th style="width:50px">UOM</th>
</tr>
</thead>
<tbody>
{% for item in doc.items %}
<tr>
  <td class="ctr">{{ loop.index }}</td>
  <td>{{ item.item_code or '' }}</td>
  <td>{{ item.item_name or '' }}</td>
  <td>{% if item.description %}<div class="item-spec">{{ item.description | safe }}</div>{% endif %}</td>
  <td>{% set make = (item.brand or '') %}{% set remark = (item.ts_item_remark or '') %}{% if make and remark %}{{ make }}<br>{{ remark }}{% else %}{{ make }}{{ remark }}{% endif %}</td>
  <td class="num">{{ frappe.format(item.qty, {'fieldtype': 'Float', 'precision': 0}) }}</td>
  <td class="ctr">{{ item.uom or item.stock_uom or '' }}</td>
</tr>
{% endfor %}
</tbody>
</table>

{% if doc.tc_name or doc.terms %}
<div class="trustbit-section-heading">Terms and Conditions</div>
<div class="trustbit-terms-body">{{ doc.terms or '' | safe }}</div>
{% endif %}

<div class="trustbit-footer">
  <div class="fname">TRUSTBIT BIOFUEL PVT LTD</div>
  <div>Bodi Junawani, Betul (M.P.)</div>
  <div>GSTN:- 23AAJCB8781D1ZM</div>
  <div>Email:- trustbitbiofuelpvtld@gmail.com | Mobile no:- 7880138508</div>
</div>

</div>
